// === family: shared ===
function heading(name) {
    return name.replace(/Widget(?:WithSource)?$|WithSource$|V\d+$/g, '')
        .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
        .replace(/([A-Za-z])\1([A-Z])/g, '$1$1 $2');
}
function panel(DIL, title, children, props = {}) {
    return DIL.h('card', { padding: 4, gap: 3, ...props },
        title ? DIL.h('title', { size: 'lg' }, title) : null, ...children);
}
function sourceLine(DIL, data) {
    const label = data.source_label || data.attribution_label || data.source_name;
    const url = data.source_url || data.attribution_provider_url;
    if (!label && !url) return null;
    return url ? DIL.h('caption', { maxLines: 1, truncate: true }, DIL.h('Link', { url, title: label || url }))
        : DIL.h('caption', { maxLines: 1, truncate: true }, label);
}
function pending(DIL, props) {
    return props.fallback
        || DIL.h('text', { role: 'status' }, 'Awaiting supplied data.');
}
function number(value) {
    const parsed = Number(String(value ?? '').replaceAll(',', ''));
    return Number.isFinite(parsed) ? parsed : null;
}
function decimal(value, digits) {
    return Number.isFinite(value)
        ? value.toLocaleString('en-US', { minimumFractionDigits: digits, maximumFractionDigits: digits })
        : '—';
}
// Renders caller-supplied data as structured content. Field names never trigger actions.
function suppliedValue(value, DIL, key = '', depth = 0) {
    if (value == null || depth > 16) return null;
    if (typeof value === 'number') return DIL.h('text', { tabularNums: true }, String(value));
    if (typeof value !== 'object') return DIL.h('text', {}, String(value));
    if (Array.isArray(value)) return DIL.h('col', { gap: 2 }, ...value.map((entry, index) =>
        DIL.h('col', { key: entry?.id ?? index, gap: 1 },
            suppliedValue(entry, DIL, key, depth + 1))));
    if (value.type && value.props && typeof value.type === 'string')
        return DIL.h('text', {}, 'Embedded widget definitions must be supplied as ui nodes.');
    const children = [];
    for (const [field, entry] of Object.entries(value)) {
        if (/^(?:__|is_loading$|dismissed$|.*_label$|.*_cta$|.*_action$|action$|handler$|resolution_id$)/.test(field)) continue;
        if (['image_url', 'imageUrl', 'thumbnail_url', 'logo_url', 'carrier_logo_url', 'image'].includes(field) && typeof entry === 'string')
            children.push(DIL.h('AsyncImage', { src: entry, alt: value.title || value.name || '' }));
        else if (['url', 'href', 'learn_more_url', 'source_url', 'website_url', 'apply_url_with_tracking', 'cta_url'].includes(field) && typeof entry === 'string')
            children.push(DIL.h('Link', { url: entry, title: value.source_name || value.title || entry }));
        else if (['title', 'heading', 'name'].includes(field) && entry != null)
            children.push(DIL.h('title', { size: 'sm' }, String(entry)));
        else if (typeof entry === 'object')
            children.push(DIL.h('col', { key: field, gap: 1 },
                DIL.h('caption', {}, field.replaceAll('_', ' ')),
                suppliedValue(entry, DIL, field, depth + 1)));
        else children.push(DIL.h('text', {}, `${field.replaceAll('_', ' ')}: ${String(entry)}`));
    }
    return DIL.h('col', { gap: 2 }, ...children);
}
function dataTable(DIL, columns, rows) {
    return DIL.h('table', {},
        DIL.h('table-section', { header: columns.map((name, index) =>
            DIL.h('table-cell', { header: true, key: name, align: index ? 'end' : 'start' }, name)) },
            ...rows.map((row, rowIndex) => DIL.h('table-row', { key: row.key ?? rowIndex },
                ...row.cells.map((cell, cellIndex) => DIL.h('table-cell',
                    { key: `${rowIndex}:${cellIndex}`, align: cellIndex ? 'end' : 'start' },
                    String(cell ?? '—')))))));
}
// === family: generic ===
function generic(props, DIL, name) {
    const data = props.__state;
    if (data == null || typeof data !== 'object' || Object.keys(data).length === 0)
        return panel(DIL, heading(name), [pending(DIL, props)]);
    return panel(DIL, data.title || data.heading || heading(name), [suppliedValue(data, DIL), sourceLine(DIL, data)]);
}

